import { NEGATIVE_NUMBER_PATTERN } from './constants.mjs';

function isHelpToken(token) {
  return token === '-h' || token === '--help';
}

function readInlineValue(token, optionName) {
  const prefix = `${optionName}=`;
  return token.startsWith(prefix) ? token.slice(prefix.length) : null;
}

function isOptionLike(token) {
  return typeof token === 'string' && token.startsWith('-');
}

function isValueToken(token) {
  if (token === undefined) {
    return false;
  }

  return !isOptionLike(token) || NEGATIVE_NUMBER_PATTERN.test(token);
}

export function parseCommandLine(argv) {
  for (const token of argv) {
    if (isHelpToken(token)) {
      return { kind: 'help' };
    }
  }

  let a;
  let b;
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--a' || token === '--b') {
      const nextToken = argv[index + 1];

      if (!isValueToken(nextToken)) {
        return {
          kind: 'error',
          message: `argument ${token}: expected one argument`,
        };
      }

      if (token === '--a') {
        a = nextToken;
      } else {
        b = nextToken;
      }

      index += 1;
      continue;
    }

    const inlineA = readInlineValue(token, '--a');
    if (inlineA !== null) {
      a = inlineA;
      continue;
    }

    const inlineB = readInlineValue(token, '--b');
    if (inlineB !== null) {
      b = inlineB;
      continue;
    }

    extras.push(token);
  }

  const missing = [];
  if (a === undefined) {
    missing.push('--a');
  }
  if (b === undefined) {
    missing.push('--b');
  }

  if (missing.length > 0) {
    return {
      kind: 'error',
      message: `the following arguments are required: ${missing.join(', ')}`,
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      message: `unrecognized arguments: ${extras.join(' ')}`,
    };
  }

  return {
    kind: 'run',
    args: { a, b },
  };
}

